async function run(pat, secs) {
  const xp0 = sdk.getSkillXp('Mining') ?? 0;
  const t0 = Date.now();
  let ores = 0;
  while (Date.now() - t0 < secs * 1000) {
    const s = sdk.getState();
    if (!s) { await sdk.waitForTicks(1); continue; }
    if (s.dialog?.isOpen) { await bot.dismissBlockingUI(); continue; }
    if (s.inventory.length >= 28) {
      const r = await bot.dropItem(/ore$/i, 'all');
      continue;
    }
    let rock = await sdk.scanFindNearbyLoc(pat, 25);
    if (!rock) { await sdk.waitForTicks(2); continue; }
    const xpBefore = sdk.getSkillXp('Mining') ?? 0;
    await sdk.sendInteractLoc(rock.x, rock.z, rock.id, 1);
    await sdk.waitForTicks(1);
    const xpAfter = sdk.getSkillXp('Mining') ?? 0;
    if (xpAfter > xpBefore) ores += (xpAfter - xpBefore);
  }
  const xp = (sdk.getSkillXp('Mining') ?? 0) - xp0;
  const dt = (Date.now() - t0) / 1000;
  return { xp, secs: +dt.toFixed(1), rawPerMin: +(xp/dt*60).toFixed(0), scorePerMin: +(xp/dt*60/200).toFixed(1) };
}
